using System.Data;using Essco.Application.Payroll;using Microsoft.Data.SqlClient;namespace Essco.Infrastructure.Data;
public sealed class SqlServerPayrollJournalRepository(string connectionString,int timeout):IPayrollJournalRepository
{public async ValueTask<PayrollJournal?>GetAsync(int number,CancellationToken t){await using var c=new SqlConnection(connectionString);await c.OpenAsync(t);string? memo;await using(var h=new SqlCommand("SELECT [Comentario] FROM [dbo].[Planilla] WHERE [Consecutivo]=@Number",c){CommandTimeout=timeout}){h.Parameters.Add("@Number",SqlDbType.Int).Value=number;memo=Convert.ToString(await h.ExecuteScalarAsync(t));}if(memo is null)return null;var lines=new List<PayrollJournalLine>();await using var cmd=new SqlCommand("SP_CrearAsientoPlanilla",c){CommandType=CommandType.StoredProcedure,CommandTimeout=timeout};cmd.Parameters.Add("@IdPlanilla",SqlDbType.Int).Value=number;var code=cmd.Parameters.Add("@pCodError",SqlDbType.Int);code.Direction=ParameterDirection.Output;var message=cmd.Parameters.Add("@pMensajeError",SqlDbType.VarChar,300);message.Direction=ParameterDirection.Output;await using var r=await cmd.ExecuteReaderAsync(t);while(await r.ReadAsync(t))lines.Add(new(Convert.ToString(r["NumeroCuenta"])?.Trim()??"",r["Debit"] is DBNull?0:Convert.ToDecimal(r["Debit"]),r["Credit"] is DBNull?0:Convert.ToDecimal(r["Credit"])));return new(number,memo,lines);}}
